[{"id": "VRLUb6aDQksRmGDk0gm6aMbz4UTHYGSL", "function": {"index": 0, "name": "write_file", "arguments": {"path": "protocol.py", "content": "def next_action(result):
    """
    Determine the next action based on the command result.

    Expected result format (as per the asynchronous command state):
    - status: one of 'running', 'completed', 'failed'
    - process_id: integer or string identifier of the process
    - exit_code: integer exit code for completed results (present only if status == 'completed')
    """
    status = result.get('status', '').lower()
    if status == 'running':
        # Return get_process_status tool with process_id
        process_id = result.get('process_id')
        if process_id is None:
            raise ValueError("Missing process_id in result")
        return {
            'tool': 'get_process_status',
            'process_id': process_id
        }
    elif status == 'completed':
        exit_code = result.get('exit_code', 0)
        if exit_code == 0:
            # success True
            return {
                'tool': 'final_report',
                'success': True
            }
        else:
            # nonzero exit -> success False
            return {
                'tool': 'final_report',
                'success': False
            }
    elif status == 'failed':
        # success False
        return {
            'tool': 'final_report',
            'success': False
        }
    else:
        # Unknown status
        raise ValueError(f"Unknown status: {status}")"}}}]

